import { neonColors } from "../constants/color";
import { CSSProperties, useState} from "react";
import { IoCloseCircle } from "react-icons/io5";
import { CreateEditCardProps } from "../types";

const CreateEditCard = ({toggleNewCard}:CreateEditCardProps) => {
  const color = neonColors[0];
  const [title, setTitle] = useState('');
  const [description, sesetDescription] = useState('');
  //   const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
  //     useSortable({ id});

  const style: CSSProperties = {
    padding: 8,
    marginBottom: 8,
    borderWidth: 2,
    color: color,
    borderStyle: "solid",
    borderColor: color,
    borderRadius: 10,
    display: "flex",
    flexDirection: "row",
    alignItems:'center',
    justifyContent:'space-between',
  };
  const textInput = (handler:(e:string)=>void) => {
    return (
      <input
        style={{
          backgroundColor: "transparent",
          marginBottom: 2,
          borderWidth: 0,
          borderStyle: "solid",
          borderBottomWidth:1,
          display:'flex'
        }}
        onChange={(e)=>handler(e)}
      />
    );
  };
  return (
    <div style={style}>
      <div style={{display:'flex',width: '80%',flexDirection:'column'}}>
      {textInput(setTitle)}
      {textInput(sesetDescription)}
      </div>
      <div style={{display:'flex'}}><IoCloseCircle size={20} onClick={toggleNewCard}/></div>
    </div>
  );
};

export default CreateEditCard;
